import{G as e,K as t,n,ot as r}from"./chunks/framework.C8_jer4d.js";var i=JSON.parse(`{"title":"Pre-Lab — Install the BAW Modes and Skills","description":"","frontmatter":{"title":"Pre-Lab — Install the BAW Modes and Skills"},"headers":[],"relativePath":"baw-lab/install-baw-modes/index.md","filePath":"baw-lab/install-baw-modes/index.md"}`),a={name:`baw-lab/install-baw-modes/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="pre-lab-—-install-the-baw-modes-and-skills" tabindex="-1">Pre-Lab — Install the BAW Modes and Skills <a class="header-anchor" href="#pre-lab-—-install-the-baw-modes-and-skills" aria-label="Permalink to “Pre-Lab — Install the BAW Modes and Skills”">​</a></h1><p>Before you start the first, you set up your laptop so that Bob understands IBM Business Automation Workflow. In this mandatory exercise you prepare a lab folder, open it as your Bob workspace, and install the <strong>IBM BAW Author</strong> and <strong>IBM BAW Admin</strong> modes together with the BAW skills.</p><p>You do not need any prior experience with genAI or IBM Bob. Every step is described, for both Windows and macOS / Linux.</p><h2 id="🧩-two-concepts-you-need-to-know" tabindex="-1">🧩 Two concepts you need to know <a class="header-anchor" href="#🧩-two-concepts-you-need-to-know" aria-label="Permalink to “🧩 Two concepts you need to know”">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>What it is</th><th>BAW example</th></tr></thead><tbody><tr><td><strong>Mode</strong></td><td>Shapes how Bob approaches a task: its role, its expertise, and which skills it reaches for.</td><td><strong>IBM BAW Author</strong> behaves like a BAW process-authoring expert. <strong>IBM BAW Admin</strong> behaves like a BAW operations and administration assistant.</td></tr><tr><td><strong>Skill</strong></td><td>A focused instruction set (a <code>SKILL.md</code> file, sometimes with helper scripts) that gives Bob one specific capability.</td><td>The <code>baw-project-doc</code> skill reads a TWX export and writes documentation for it.</td></tr></tbody></table><p>Some of the skills run Python scripts. That is why Python is part of the pre-requisites.</p><h2 id="🎯-what-you-will-learn" tabindex="-1">🎯 What you will learn <a class="header-anchor" href="#🎯-what-you-will-learn" aria-label="Permalink to “🎯 What you will learn”">​</a></h2><ul><li>How to organise the lab material in one folder (<code>bob-baw-workshop</code>) on your laptop</li><li>How to open the lab folder as a workspace in Bob IDE and trust it</li><li>How to install the BAW modes and skills globally, so they are available in every Bob workspace</li><li>How to check that the <strong>IBM BAW Author</strong> and <strong>IBM BAW Admin</strong> modes are available in Bob</li></ul><h2 id="✅-before-you-begin" tabindex="-1">✅ Before you begin <a class="header-anchor" href="#✅-before-you-begin" aria-label="Permalink to “✅ Before you begin”">​</a></h2><p>Make sure you have the following. These were part of the pre-requisites you received by email.</p><ul><li>A valid IBMid. You need this to sign in to IBM Bob.</li><li>IBM Bob IDE is installed and running.</li><li>Python 3.13 or later installed.</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};